              </Link>
            ))}
          </div>
        </div>
      )}

      {/* STICKY BOTTOM BUTTONS */}
      <div className="fixed bottom-0 left-0 right-0 z-30 bg-white border-t border-neutral-light/70 p-3 pb-safe flex gap-3 shadow-glow md:hidden">
        <button
